using System;
using System.Collections.Generic;
using System.Linq;
namespace MaritimeLegend.Domain {
public partial class GameService : IMarketService,IProductionService {
        public string Build(int industry){var city=S.cities[S.city];if(!city.license)return "请先到市政厅获取产业许可证";int level=city.factories[industry];if(level>=5)return "工厂已达到5级";int cost=C.factories[industry].price*(level+1);if(S.gold<cost)return "金币不足，需要 "+cost;S.gold-=cost;city.factories[industry]++;return "工坊已建设/升级至 "+(level+1)+" 级";}
        public string Start(string id,int city){var r=C.Recipe(id);var cs=S.cities[city];int level=Skills.EffectiveLevel(S,city,r.industry);if(!cs.license||cs.factories[r.industry]<1)return "需要本城对应工坊";if(level<r.minLevel)return "工艺等级不足";if(S.orders.Count(o=>o.city==city&&!o.claimed&&!o.cancelled&&C.Recipe(o.recipe).industry==r.industry)>=cs.factories[r.industry])return "工坊订单槽位已满，请领取成品或升级";foreach(var x in r.inputs)if(Inventory.Count(cs.warehouse,x.product)<x.quantity)return "仓库缺少 "+C.Product(x.product).name;int fee=ProductionFee(r,city);if(S.gold<fee)return "加工费用不足";var order=new Order{id=Guid.NewGuid().ToString("N"),ownerId=S.ownerId,recipe=id,city=city,effectiveLevel=level};foreach(var x in r.inputs)order.locked.AddRange(Inventory.Take(cs.warehouse,x.product,x.quantity));order.quality=quality.Roll(order.locked.Max(x=>x.quality),level,r.difficulty-(city==2||city==7?.08:0),ref S.seed);S.gold-=fee;S.orders.Add(order);return "工单已开始；原料已锁定，品质结果已固定";}
        int ProductionFee(Recipe r,int city){return Math.Max(1,(int)Math.Ceiling(r.fee*((city==3&&(r.industry==6||r.industry==7))||(city==5&&r.industry==2)?.92:1)*(HasPartner(6)&&r.industry==7?.95:1)));}
        public double Duration(Order o,bool offline){var r=C.Recipe(o.recipe);double basis=offline?r.offlineHours*3600:S.city==o.city&&!S.atSea?r.foregroundSeconds:r.awayCityMinutes*60;double floor=offline?7200:S.city==o.city&&!S.atSea?5:300;double factor=1-.02*(o.effectiveLevel-1);if(HasPartner(4))factor*=.92;if((o.city==0&&(r.industry==2||r.industry==3))||(o.city==1&&r.industry==0)||(o.city==4&&(r.industry==2||r.industry==4))||(o.city==6&&r.industry==3))factor*=.9;return Math.Max(floor,basis*factor);}
        public void Advance(double seconds,bool offline){if(seconds<=0||S.settings.productionPaused)return;foreach(var o in S.orders.Where(x=>!x.completed&&!x.cancelled).ToList()){o.progress=Math.Min(1,o.progress+seconds/Duration(o,offline));if(o.progress>=1){o.completed=true;S.produced++;Gain(7,12);Emit("production");if(C.Recipe(o.recipe).output=="flagship"&&o.quality<=2)S.instrumentMade=true;if(C.Product(C.Recipe(o.recipe).output).name=="船帆")S.sailsMade=true;}}if(!offline)foreach(var ready in S.orders.Where(x=>x.completed&&!x.claimed&&!x.cancelled&&(x.repeat||x.autoSell)).ToList())Claim(ready.id);CheckQuest();}
        public string Claim(string id){var o=S.orders.First(x=>x.id==id);if(!o.completed||o.claimed||o.cancelled)return "工单未完成或已经领取";var r=C.Recipe(o.recipe);var inv=S.cities[o.city].warehouse;if(Inventory.Weight(inv)+C.Product(r.output).weight*r.quantity>inv.capacity)return "仓库已满，请先转移货物";o.claimed=true;Inventory.Add(inv,r.output,o.quality,r.quantity,o.city);if(o.autoSell)Trade(o.city,r.output,o.quality,r.quantity,false,inv);if(o.repeat)Start(o.recipe,o.city);return "已领取 "+C.Product(r.output).name+" ×"+r.quantity+" · 品质"+QualityName(o.quality);}
        public string Cancel(string id){var o=S.orders.First(x=>x.id==id);if(o.completed||o.claimed||o.cancelled)return "已完成订单不可取消";var inv=S.cities[o.city].warehouse;var refunds=o.locked.Select(b=>new Batch(b.product,b.quality,b.quantity/2,b.origin)).ToList();if(Inventory.Weight(inv)+refunds.Sum(b=>C.Product(b.product).weight*b.quantity)>inv.capacity)return "仓库不足以接收退款";o.cancelled=true;foreach(var b in refunds)Inventory.Add(inv,b.product,b.quality,b.quantity,b.origin);return "已取消，按各批次向下取整退还50%原料；加工费不退";}
        public void RecoverOffline(DateTime now){DateTime last;if(!DateTime.TryParse(S.lastUtc,null,System.Globalization.DateTimeStyles.RoundtripKind,out last))return;double elapsed=(now-last.ToUniversalTime()).TotalSeconds;if(elapsed<0||elapsed>86400){Log("离线时钟异常或超出24小时：按上限修正；不自动循环生产。");elapsed=Clamp(elapsed,0,86400);}Advance(elapsed,true);S.lastUtc=now.ToString("O");}
}}
